import{_ as t,o,c as a,ae as i}from"./chunks/framework.Czhw_PXq.js";const h=JSON.parse('{"title":"ADR 009: UI Theme, Routing & Brand Identity","description":"","frontmatter":{},"headers":[],"relativePath":"adr/009-ui-theme-routing.md","filePath":"adr/009-ui-theme-routing.md"}'),n={name:"adr/009-ui-theme-routing.md"};function r(d,e,l,s,c,u){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-009-ui-theme-routing-brand-identity" tabindex="-1">ADR 009: UI Theme, Routing &amp; Brand Identity <a class="header-anchor" href="#adr-009-ui-theme-routing-brand-identity" aria-label="Permalink to &quot;ADR 009: UI Theme, Routing &amp; Brand Identity&quot;">​</a></h1><p><strong>Date</strong>: 2026-01-25 <strong>Status</strong>: Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Initial iterations of the frontend used a generic &quot;black&quot; dark mode and lacked a centralized routing strategy for the Landing Page and Dashboard transition. The user highlighted issues with:</p><ol><li><strong>Contrast</strong>: The &quot;pitch black&quot; (<code>#000000</code>) background was too aggressive.</li><li><strong>Identity</strong>: Lack of brand colors (Emerald/Gold) in the Landing Page.</li><li><strong>Routing</strong>: <code>useRoutes</code> errors and lack of authenticated route protection.</li></ol><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>We have decided to:</p><ol><li><p><strong>Adopt a &quot;Soft Charcoal&quot; Dark Theme</strong>:</p><ul><li>Replace pure black with <code>#1a1c1a</code> (Deep Stone/Charcoal) and <code>#242B33</code> (Slate) variants.</li><li>This reduces eye strain and provides a more premium feel.</li><li>Global CSS variables and Tailwind config updated (<code>colors.brand.dark</code>).</li></ul></li><li><p><strong>Harmonize Brand Identity</strong>:</p><ul><li><strong>Primary Action Color</strong>: Emerald Green (<code>emerald-600</code>) for consistency with the Dashboard.</li><li><strong>Accent/Luxury Color</strong>: Metallic Gold (<code>#C5A028</code>) for specific high-value elements (Logos, &quot;Pliego&quot; terminology, Upload Icons).</li><li><strong>Landing Page</strong>: Uses a &quot;Light Sage to Stone&quot; gradient (<code>#E8E6DE</code> -&gt; <code>#B8C1B7</code>) to contrast with the dark Dashboard, creating a &quot;Day/Night&quot; transition effect upon login.</li></ul></li><li><p><strong>Implement Client-Side Routing</strong>:</p><ul><li>Use <code>react-router-dom</code> v6.</li><li><code>App.tsx</code> serves as the Router root.</li><li>Routes: <ul><li><code>/</code> (Landing Page - Public)</li><li><code>/login</code>, <code>/register</code> (Auth - Public, Centered Layout)</li><li><code>/dashboard</code> (App - Protected/Private)</li></ul></li></ul></li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><h3 id="positive" tabindex="-1">Positive <a class="header-anchor" href="#positive" aria-label="Permalink to &quot;Positive&quot;">​</a></h3><ul><li><strong>Cohesive UX</strong>: Seamless transition between marketing (Landing) and product (Dashboard).</li><li><strong>Visual Comfort</strong>: Reduced harsh contrast in dark mode.</li><li><strong>Maintainability</strong>: Centralized router makes adding future pages (e.g., <code>/settings</code>, <code>/history</code>) trivial.</li></ul><h3 id="negative" tabindex="-1">Negative <a class="header-anchor" href="#negative" aria-label="Permalink to &quot;Negative&quot;">​</a></h3><ul><li><strong>Complexity</strong>: Two distinct visual themes (Light Landing vs Dark Dashboard) requires careful CSS management to avoid &quot;FOUC&quot; (Flash of Unstyled Content) or theme bleeding.</li></ul>',13)])])}const m=t(n,[["render",r]]);export{h as __pageData,m as default};
